{
  "service": "phase2-complex",
  "action": "echo",
  "componentType": "rest",
  "description": "Runnable Phase 2 JSON echo with all supported sections",
  "config": {
    "request": {
      "uri": "{{upstream_url}}/anything",
      "method": "POST",
      "contentType": "application/json",
      "headers": { "X-Customer-Id": "{$context.id}", "X-Request-Label": "demo-{$context.label}" },
      "payloadTemplate": { "customerId": "{$context.id}", "name": "{$context.name}", "items": "{$context.items}" }
    },
    "timeout": { "response": 5000 },
    "resilience": {
      "retryCount": 2, "retryDelay": 100, "backoff": "exponential", "maxDelay": 1000,
      "retryOn": [500, 502, 503], "rateLimit": { "requests": 20, "windowMs": 60000 }
    },
    "output": {
      "validation": { "rules": [{ "expression": "{$output.json.customerId} != null", "message": "Echo omitted customer ID", "errorPath": "{$output.message}" }] },
      "default": { "json": { "customerId": "no-body" } },
      "transformation": { "echoResponse": { "customerId": "{$output.json.customerId}", "name": "{$output.json.name}", "items": "{$output.json.items}" } }
    }
  },
  "condition": "{$context.enabled} == true && {$context.id} != null",
  "metaData": { "example": "phase2", "purpose": "dummy-data-only" }
}

{
  "service": "phase2-complex", "action": "default", "componentType": "rest",
  "config": {
    "request": { "uri": "{{upstream_url}}/status/204", "method": "GET", "contentType": "application/json", "headers": { "X-Demo": "{$context.id}" }, "payloadTemplate": { "unusedForGet": "{$context.id}" } },
    "timeout": { "response": 5000 },
    "resilience": { "retryCount": 1, "retryDelay": 100, "backoff": "fixed", "maxDelay": 500, "retryOn": [503], "rateLimit": { "requests": 20, "windowMs": 60000 } },
    "output": { "validation": { "rules": [{ "expression": "true", "message": "Default scenario permits an empty response" }] }, "default": { "status": "empty" }, "transformation": { "defaultResponse": { "status": "{$output.status}", "customerId": "{$context.id}" } } }
  },
  "condition": "{$context.id} != null", "metaData": { "example": "phase2-default" }
}

